class Bloom {
  constructor(m, k) {
    this.m = m; this.k = k;
    this.bits = new Uint8Array(Math.ceil(m / 8));
  }
  positions(item) {
    const out = [];
    for (let i = 0; i < this.k; i++) out.push(hash(item, i) % this.m);
    return out;
  }
  add(item) {
    for (const p of this.positions(item)) this.bits[p >> 3] |= 1 << (p & 7);
  }
  mightContain(item) {
    return this.positions(item).every(p => (this.bits[p >> 3] & (1 << (p & 7))) !== 0);
  }
}
